window.MONSTER_CHUNK_11 = [{"name":"Giant Gecko","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":6,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":5,"will":2,"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"bite +2 (2d4+1)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":15,"constitution":12,"intelligence":2,"wisdom":14,"charisma":7,"baseatk":1,"cmb":2,"cmd":14,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Climb","value":21},{"skill":"Perception","value":6}],"sq":[{"type":"expert climber"}],"environments":["warm forests","warm mountains"],"organizations":["solitary","pair","nest (3-6)"],"treasure":"none","description_visual":"With large bulging eyes to spot prey from afar, this oversized, smooth-scaled lizard has splayed, padded ft. and a toothy maw.","group":"Lizard","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Expert Climber","kind":"Ex","details":"A gecko's ft. allow it to climb virtually any surface, no matter how slick or sheer. In effect, geckos are treated as constantly being under a natural version of the spell spider climb."}],"description":"These lizards are mostly docile and shy away from attacking creatures larger than a cat or dog. Despite their shyness, they are ultimately curious creatures, and often approach bigger creatures simply to investigate. Of course, a giant gecko is more than capable of defending itself, biting creatures that react violently to the lizard when fleeing isn't an option.\n\nSome humanoids train giant geckos as bestial guardians. Smaller humanoids (in particular, goblins) can even use the creatures as mounts, taking advantage of their superior climbing skills to attack from seemingly impossible positions and angles. A giant gecko measures 8 ft. from nose to tail and weighs 120 pounds. Coloration among giant geckos can vary wildly, though most are some shade of green.","ecology":"","habitat_society":""},{"name":"Giant Solifugid","cr":1,"xp":400,"alignment":"N","size":"Small","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":2,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":50},{"type":"climb","speed":30}],"melee":"bite +3 (1d6+1), 2 claws +3 (1d3+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d3+1"}],"strength":12,"dexterity":15,"constitution":15,"wisdom":11,"charisma":2,"baseatk":1,"cmb":1,"cmd":13,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":9},{"skill":"Perception","value":4},{"skill":"Stealth","value":10}],"environments":["warm deserts"],"organizations":["solitary","pair","colony (3-6)"],"treasure":"none","description_visual":"This tan-colored creature looks like a ten-legged spider. Oversized jaws grind together slowly beneath beady eyes.","group":"Solifugid","source":"PFRPG Bestiary 2","description":"Solifugids are sometimes called \"camel spiders,\" \"wind scorpions,\" or \"sun spiders,\" despite the fact that they are neither spiders nor scorpions but rather their own unique species. They have large pedipalps near their heads, used to grab and hold prey while they feed with their twin sets of vertically aligned mandibles. When hunting in groups, they prefer to attack targets already grappled by other solifugids. The various species of enormous solifugids generally have eight legs, although the front two appendages are large enough that they can easily be mistaken for an additional pair of legs. Some species, like the albino cave solifugid, have fewer legs, but all solifugids are aggressive vermin. The following table lists the most common variants beyond the two presented above. Many of these species have additional unique abilities, such as the razormouth's ability to cause hideous, bleeding wounds in those it attacks. Species CR Size HD Dog-eating 1/2 Tiny 1 Yellow terror 8 Large 10 Razormouth 11 Huge 13 Banshee 15 Gargantuan 16 Duneshaker 18 Colossal 20.","ecology":"","habitat_society":""},{"name":"Giant Spider","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"vermin","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+1 armor, +3 Dex","hp":16,"hd":"3d8+3","hdvalue":3,"fort":4,"ref":4,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"bite +2 (1d6 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"web","details":"+5 ranged, DC 12, hp 2"}],"strength":11,"dexterity":17,"constitution":12,"wisdom":10,"charisma":2,"baseatk":2,"cmb":2,"cmd":15,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":16},{"skill":"Perception","value":4,"special":"+8 in webs"},{"skill":"Stealth","value":7,"special":"+11 in webs"}],"environments":["any"],"organizations":["solitary","pair","colony (3-8)"],"treasure":"incidental","description_visual":"A spider the size of a man crawls silently from the depths of its funnel-shaped web.","group":"Spider","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 14; frequency 1/round for 4 rounds; effect 1d2 Strength damage; cure 1 save."}],"description":"The statistics above are for a web-spinning spider. Hunting spiders lose the web ability but gain a +8 racial modifier on Acrobatics checks. All giant spiders have a +2 racial bonus on poison save DCs. Other species of giant spiders exist, as detailed below. Species CR Size HD Scarlet spider 1/4 Tiny 1d8 Giant crab spider 1/2 Small 2d8 Giant black widow 3 Large 5d8 Ogre spider 5 Huge 7d8 Giant tarantula 8 Gargantuan 10d8 Goliath spider 11 Colossal 14d8.","ecology":"","habitat_society":""},{"name":"Giant Tick","cr":1,"xp":400,"alignment":"N","size":"Small","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":16,"ac_touch":11,"ac_flat_footed":16,"ac_mods":"+5 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":0,"will":0,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"bite +2 (1d4 plus grab, attach, and disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1 Constitution"}],"strength":11,"dexterity":10,"constitution":15,"wisdom":11,"charisma":2,"baseatk":1,"cmb":0,"cmb_special":"+8 vs. grapple","cmd":10,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":8},{"skill":"Stealth","value":8}],"environments":["temperate forests"],"organizations":["solitary","pair","cluster (3-6)","nest (7-12)"],"treasure":"none","description_visual":"This dog-sized tick has a grotesquely bulbous body and a thin head equipped with hooked mandibles.","group":"Tick","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Grab","kind":"Ex","details":"A giant tick can grab targets of any size, and has a +8 racial bonus on grapple checks rather than the normal +4 bonus most creatures with grab possess."},{"type":"Disease","kind":"Ex","details":"Red ache: Bite-injury; save Fort DC 13; onset 1d3 days; frequency 1/day; effect 1d6 Str damage; cure 2 consecutive saves. The DC is Constitution-based."}],"description":"In areas where large creatures like megafauna or dinosaurs dwell, the giant tick behaves much like its smaller kin-it lies in wait in the undergrowth, and when a suitable host passes by, it drops onto the body to feed. In other areas, these vermin are much more aggressive, and actively hunt smaller prey like dogs, livestock, or even humanoids. A giant tick drains blood quickly, but once it has caused 6 points of Constitution damage, it drops off, sated, to crawl away to digest. A giant tick is 3 ft. long and weighs 50 pounds.","ecology":"","habitat_society":""},{"name":"Giant Tortoise","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":-2,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":8,"ac_flat_footed":16,"ac_mods":"-2 Dex, +8 natural","hp":22,"hd":"3d8+9","hdvalue":3,"fort":8,"ref":1,"will":2,"speed":[{"type":"land","speed":10}],"melee":"bite +4 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":7,"constitution":16,"intelligence":2,"wisdom":13,"charisma":9,"baseatk":2,"cmb":4,"cmd":12,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Great Fortitude"}],"skills":[{"skill":"Perception","value":7,"special":"+3 for sound-based checks"}],"sq":[{"type":"buoyant"},{"type":"shell"},{"type":"slow and steady"}],"environments":["warm deserts","warm islands"],"organizations":["solitary","pair","herd (6-12)"],"treasure":"none","description_visual":"This tortoise is half the height of a human, and has a domed shell, leathery skin, and a long neck.","group":"Tortoise","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Buoyant","kind":"Ex","details":"A tortoise that fails a Swim check by 5 or more doesn't sink."},{"type":"Shell","kind":"Ex","details":"As a move action, a tortoise can pull its extremities and head into its shell. It can't move or attack as long as it remains in this state, but its armor bonus from natural armor increases by 4 as long as it does. It may end this state as a move action."},{"type":"Slow and Steady","kind":"Ex","details":"A tortoise's speed is never modified by armor or encumbrance."}],"description":"Giant tortoises typically live on tropical islands without large predators. Despite their impressive shells, their slow speed makes them easy prey, especially for vermin and other creatures that consume their eggs. Tortoises are herbivores, and can survive for months or even years without food or water. Despite being poor swimmers, their buoyancy and long necks capable mean they can survive for significant periods at sea. A typical giant tortoise is 3-1/2 ft. tall to the top of the shell and weighs 500 pounds.","ecology":"","habitat_society":""},{"name":"Giant Water Strider","cr":1,"xp":400,"alignment":"N","size":"Large","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":12,"ac_touch":10,"ac_flat_footed":11,"ac_mods":"+1 Dex, +2 natural, -1 size","hp":19,"hd":"3d8+6","hdvalue":3,"fort":5,"ref":2,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":20,"maneuverability":"poor"}],"melee":"2 claws +2 (1d4+1), bite +2 (1d2+1)","space":"10 ft.","reach":"5 ft.","strength":13,"dexterity":13,"constitution":14,"wisdom":10,"charisma":2,"baseatk":2,"cmb":4,"cmd":16,"cmd_special":"+8 vs. trip","skills":[{"skill":"Fly","value":-5},{"skill":"Perception","value":4},{"skill":"Swim","value":5}],"sq":[{"type":"water skating"}],"environments":["any water"],"organizations":["solitary","colony (2-9)"],"treasure":"incidental","description_visual":"This bug has long, fuzzy legs that support it on the water's surface as if the creature stands on solid ground.","group":"Water Strider","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Tremorsense","kind":"Ex","details":"A water strider's tremorsense functions only when the creature is in contact with the water's surface."},{"type":"Water Skating","kind":"Ex","details":"A water strider can move on the surface of water as if it were on land. A water strider swimming at the water's surface can pull itself onto the water with a successful Swim check."}],"description":"A giant water strider is a long-legged insect with the ability to walk on water. It feeds on fish and birds. Water striders use their weak flight only to escape predators or for seasonal migrations to new breeding areas. They are sometimes kept as mounts by coast-dwelling humanoids. A giant water strider lives 1-2 years. Carrying more than a light load (200 pounds) prevents a giant water strider from using its water skating ability.","ecology":"","habitat_society":""},{"name":"Giant Weasel","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":4,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":14,"ac_flat_footed":11,"ac_mods":"+4 Dex, +1 natural","hp":9,"hd":"2d8","hdvalue":2,"fort":3,"ref":7,"will":1,"speed":[{"type":"land","speed":40}],"melee":"bite +5 (1d6+3 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d2 Con"},{"type":"grab"}],"strength":14,"dexterity":19,"constitution":10,"intelligence":2,"wisdom":13,"charisma":11,"baseatk":1,"cmb":3,"cmb_special":"+4 vs. grapple","cmd":17,"cmd_special":"+4 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":6},{"skill":"Perception","value":7},{"skill":"Stealth","value":10},{"skill":"Swim","value":8}],"sq":[{"type":"compression"}],"environments":["any land"],"organizations":["solitary","pair","den (3-6)"],"treasure":"incidental","description_visual":"The predatory nature of this wolf-sized creature is revealed by its long teeth, sleekly muscular body, and belligerent hiss.","group":"Weasel","source":"PFRPG Bestiary 4","description":"Like their smaller cousins, giant weasels have long, slender bodies and short legs, and come in a variety of colors from reddish brown to snowy white. Giant weasels are active and tenacious predators, and have a reputation for being as clever as they are quick. Both highly aggressive and extremely territorial, they frequently attack creatures that are much larger than they are. Giant weasels are often trained to serve as guards and mounts by various Small humanoid s . Adult giant weasels can grow to be 5 ft. long, stand as high as 2-1/2 ft. tall at the shoulder, and weigh up to 150 pounds.","ecology":"","habitat_society":""},{"name":"Gnoll","cr":1,"xp":400,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["gnoll"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+2 armor, +1 natural, +2 shield","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":0,"will":0,"speed":[{"type":"land","speed":30}],"melee":"spear +3 (1d8+3/x3)","ranged":"spear +1 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":10,"constitution":13,"intelligence":8,"wisdom":11,"charisma":8,"baseatk":1,"cmb":3,"cmd":13,"feats":[{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":2}],"languages":["Gnoll"],"environments":["any deserts","warm plains"],"organizations":["solitary","pair","hunting party (2-5 gnolls and 1-2 hyenas)","band (10-100 adults plus 50% noncombatant children, 1 sergeant of 3rd level per 20 adults, 1 leader of 4th-6th level, and 5-8 hyenas)","tribe (20-200 plus 1 sergeant of 3rd level per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 7-12 hyenas, and 4-7 hyaenodons)"],"treasure":"NPC Gear (leather armor, heavy wooden shield,  battleaxe, longbow with 20 arrows)","description_visual":"Hunched and feral, this furred, hyena-headed humanoid stands slightly taller than the average human.","source":"PFRPG Bestiary","description":"Gnolls are a race of hulking, humanoids that resemble hyenas in more than mere appearance; they show a striking affinity with the scavenging animals, to the point of keeping them as pets, and ref lect many of the lesser creatures' behaviors.\n\nGnolls are capable hunters, but are far happier to scavenge or steal a kill than to go out and track down prey. This laziness impels them to acquire slaves of whatever type is available, whom they force to dig warrens, gather supplies and water, and even hunt for their gnoll masters.\n\nCreatures other than hyenas and other gnolls are either meat or slaves, depending upon the temperament of the tribe. Even a dead or fallen comrade is a fresh meal for a gnoll, who might honor a distinguished tribe member with a brief prayer, or thoroughly cook one that has died of a wasting disease, but otherwise view a dead gnoll as little different from any other creature. The more \"civilized\" gnolls don't eat their prisoners, but instead keep them as slaves, either to defend or improve their lair or to trade with other tribes or slaver bands.\n\nGnolls relish combat, but only when they have the obvious advantage of numbers. In other situations, they prefer to avoid combat except as a means of winning a kill from another hunter, or as a clever ambush to bring down a large meal. These hyena-men see no value in courage or valor, instead preferring to flee once it becomes clear that victory isn't possible, noting that it is better to run with tail tucked away than to lose one's tail entirely.\n\nDuring combat, gnolls use a strange mixture of pack tactics and individual standoffs. If a gnoll feels that it is winning, it attempts to take down a weaker being rather than aiding its fellows. If the gnolls are struggling, they gang up on a powerful leader and try to take that creature down, in the hopes of forcing its allies to flee.\n\nGnoll leaders are typically rangers, although clerics are highly regarded as well. Most gnolls find arcane magic difficult to master, and as a result it is relatively rare to see a gnoll bard, sorcerer, or wizard.","ecology":"","habitat_society":""},{"name":"Goblin Dog","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":13,"ac_touch":12,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 natural","hp":9,"hd":"1d8+5","hdvalue":1,"fort":4,"ref":4,"will":1,"immunities":["disease"],"speed":[{"type":"land","speed":50}],"melee":"bite +2 (1d6+3 plus allergic reaction)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":14,"constitution":15,"intelligence":2,"wisdom":12,"charisma":8,"baseatk":0,"cmb":2,"cmd":14,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Stealth","value":6}],"environments":["any swamps","temperate forests","any underground"],"organizations":["solitary","pack (2-12)"],"treasure":"none","description_visual":"This mangy canine's face has the same flat nose, beady eyes, and protruding teeth as a rat grown grotesquely large.","source":"PFRPG Bestiary","special_abilities":[{"type":"Allergic Reaction","kind":"Ex","details":"A goblin dog's dander is highly irritating to all creatures save those with the goblinoid subtype. A non-goblinoid creature damaged by a goblin dog's bite, who deals damage to a goblin dog with a natural weapon or unarmed attack, or who otherwise comes into contact with a goblin dog (including attempts to grapple or ride the creature) must make a DC 12 Fortitude save or break out in an itching rash. A creature affected by this rash takes a -2 penalty to Dexterity and Charisma for 1 day (multiple allergic reactions don't stack). Remove disease or any magical healing removes the rash instantly. This is a disease effect. The save DC is Constitution-based."}],"description":"Loathed by men and beasts alike, goblin dogs are ugly, stinking, craven, and foul-tempered. It's no surprise that goblins find kindred spirits in these shunned, disgusting beasts. Constantly itching, aff licted with a species-wide mange exacerbated by prolific dander, even the healthiest goblin dog looks sickly and starved. Despite its name, the goblin dog is in fact a species of rodent grown monstrously large. Their long-legged shape and proclivity to hunt and run in packs earned them their popular name, a name that many goblins take issue with, as it galls the average goblin to consider these, their favored mounts, having anything at all to do with actual dogs. Of course, being goblins, they haven't bothered to come up with alternate names for goblin dogs. Perhaps they don't realize they can. Contact with a goblin dog's infested, mangy hide causes most other creatures to break out into hives, a condition known as \"goblin rash.\" Goblinoids seem to be immune to this affliction, and are fond of keeping goblin dogs as guardians and mounts. Despite their skin conditions and disorders, goblin dogs are highly resistant to disease. Their favored food is carrion-the riper, the better. That many goblin tribes let their goblin dogs run free in their lairs is the single reason most goblin dens aren't filthier than they actually are; constantly hungry, a goblin dog eats anything it can chew that it finds left behind by other, more discerning palates. A goblin dog is 5 ft. long but weighs only 75 pounds.","ecology":"","habitat_society":""},{"name":"Goblin Snake","cr":1,"xp":400,"alignment":"CE","size":"Small","type":"aberration","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":2,"ref":2,"will":4,"speed":[{"type":"land","speed":30},{"type":"burrow","speed":5},{"type":"swim","speed":20}],"melee":"bite +4 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"goblin breath"}],"strength":14,"dexterity":15,"constitution":14,"intelligence":9,"wisdom":12,"charisma":13,"baseatk":1,"cmb":2,"cmd":14,"cmd_special":"can't be tripped","feats":[{"feat":"Lunge","type":"bonus"},{"feat":"Skill Focus (Bluff)"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Intimidate","value":5},{"skill":"Knowledge (local)","value":3},{"skill":"Perception","value":5},{"skill":"Stealth","value":10}],"languages":["Common","Goblin"],"sq":[{"type":"snake empathy","details":"+7"}],"environments":["any swamps","any underground"],"organizations":["solitary","pair","nest (3-12 plus 1-6 venomous snakes)"],"treasure":"standard","description_visual":"A gray, lipless goblin head with serpent's fangs sits atop the sinuous black body of this greasy-scaled snake.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Goblin Breath","kind":"Ex","details":"Once every 1d4 rounds, a goblin snake can release a disgusting belch as a standard action. Any creature within 5 ft. of the goblin snake must succeed at a DC 13 Fortitude save or be sickened for 1d6 rounds by the stench. Creatures that successfully save cannot be affected by the same goblin snake's goblin breath for 24 hours. Goblin snakes and goblins are immune to this effect. This is a poison effect. The save DC is Constitution-based."},{"type":"Snake Empathy","kind":"Ex","details":"This ability functions similarly to a druid's wild empathy ability, but allows a goblin snake to verbally communicate with and be understood by snakes and similar serpentine reptiles. The bonus equals the goblin snake's racial Hit Dice plus its Charisma modifier and a +4 racial bonus."}],"description":"Tenacious predators and bullies, goblin snakes are shrill, impulsive, and endlessly hungry. When their instinctual cunning takes hold, however, these maniacal creatures exhibit all the stealth and deadly cunning of serpents coupled with the capricious destructiveness of goblins.\n\nCruel and selfish, goblin snakes care for little more than their next meals and indulging their unfounded arrogance. Like goblins, they can easily eat their body weight in food daily, but goblin snakes are also lazy, and are more likely to settle for easy meals rather than ones they must work to find. As a result, goblins snakes eat almost anything within reach and readily available, from carrion to rubbish (the source of their horrendous and nauseating breath). Goblin snakes delight in fresh meat, but strongly prefer having others bring it to them over hunting and killing it themselves.\n\nEnjoying the company of snakes, goblin snakes are often accompanied by several smaller venomous serpents, which the goblin snakes use to protect their lairs and supplement their food supply. Goblin snakes are exceedingly jealous of nagas, however, envying their serpentine majesty and mastery of magic. Enterprising and cunning goblin snakes have been known to impersonate nagas, demanding tribute and food from gullible creatures in awe of the \"naga's\" supposed magical abilities. Some scholars have noted the superficial similarities between goblin snakes and nagas, and have gone as far as to theorize that the goblin snake might be a particularly weak breed of naga-a theory that most nagas don't appreciate at all.\n\nAlthough goblin snakes are not as smart as goblins, their terrifying shape allows them to take positions of inf lated prominence within goblin society. Fearful goblins typically defer to the beasts, which well suits the goblin snakes' innate arrogance and sense of superiority. Goblin snakes affiliated with goblin tribes usually treat their goblin associates as servants at best and slaves at worst.\n\nGoblin snakes share goblins' fear of horses (who could easily step on and crush an unwary goblin snake) and love of fire (though their lack of arms gives them little opportunity to indulge in arson), but they are not as superstitious as goblins. Goblin snakes eagerly embrace magic if given the opportunity, and it isn't uncommon for a goblin snake with adept, cleric, oracle, or sorcerer class levels to serve as a goblin tribe's shaman or high priest.","ecology":"","habitat_society":""},{"name":"Gourd Leshy","cr":1,"xp":400,"alignment":"N","size":"Small","type":"plant","subtypes":["leshy","shapechanger"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size, +0 natural","hp":9,"hd":"1d8+5","hdvalue":1,"fort":4,"ref":2,"will":0,"immunities":["electricity","sonic","plant traits"],"speed":[{"type":"land","speed":20}],"melee":"slam -1 (1d3-2 plus ensnare)","ranged":"seed +3 (1 plus ensnare)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":2,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"}]}],"strength":6,"dexterity":15,"constitution":14,"intelligence":6,"wisdom":11,"charisma":15,"baseatk":0,"cmb":-3,"cmd":9,"feats":[{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":6,"special":"+10 in plains and undergrowth"},{"skill":"Survival","value":0,"special":"+4 in plains and undergrowth"}],"languages":["Druidic","Sylvan","plantspeech (gourds)"],"sq":[{"type":"change shape","details":"Small gourd; tree shape"},{"type":"keepsake"},{"type":"verdant burst"}],"environments":["any hills","any plains"],"organizations":["solitary","patch (2-16)"],"treasure":"standard","description_visual":"This little plant man walks on legs like tangled vines and has a pumpkin carved with eyes and a mouth for a head.","group":"Leshy","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Ensnare","kind":"Ex","details":"The seeds and slam attack of a gourd leshy entangle the target in vines for 2d4 rounds unless the target makes a DC 12 Reflex save. The target can attempt to burst these entangling vines before the duration expires with a DC 12 Strength check as a full-round action. The save and burst DCs are Constitution-based."},{"type":"Keepsake","kind":"Su","details":"Gourd leshys can pop off the top of their heads and store a single Fine-sized object such as a dagger or potion inside While within the leshy's head, the item is warded by nondetection. In addition, after 24 hours, the item within is cleaned and polished, and, if damaged, repaired as if by a mending spell. Both spell effects have a caster level equal to twice the leshy's Hit Dice (CL 2nd for most gourd leshys)."},{"type":"Seed","kind":"Ex","details":"A gourd leshy can hurl its seeds as a ranged attack. If it hits, this attack deals 1 point of damage (this damage isn't modified by Strength) and affects the target with the gourd leshy's ensnare ability. This attack has a 10-foot range increment."}],"description":"With tangles of leafy vines for limbs and a carved gourd for a head, gourd leshys present a rather comical appearance. Intimately connected with the harvest season, gourd leshys see to the health and sustainable harvest of crops, especially vegetables and grains.\n\nSuperstition and love of rituals run deep in gourd leshys. They do their best to exactly reproduce what worked before with every trivial activity, and change seemingly random details when attempting tasks they previously failed. Gourd leshys collect random odds and ends as good luck charms, ranging from polished stones to bird feathers to tarnished coins. Credulous to a fault, gourd leshys believe nearly anything they hear from those they trust. However, their admittedly hollow heads still hold memories, and a gourd leshy betrayed rarely forgets.\n\nAs gourd leshys aren't particularly strong, they often fight dirty. One favorite trick is to wait for an enemy to come within striking distance while in gourd form so that they can assume their true form and make a sneak attack in the same round.\n\nGROWING A GOURD LESHY\n\nGourd leshys grow best in small vegetable patches or in sunny meadows. Carving eyes and a mouth into a growing gourd leshy's \"face\" is an important part of the growth ritual, for neglecting to do this robs the gourd leshy of its ability to see or speak. The exact nature and appearance of a gourd leshy's features can vary wildly between individuals.\n\nGOURD LESHY\n\nCL 6th; Price 1,500 gp\n\nRITUAL\n\nRequirements Knowledge (nature) 5 ranks, entangle, plant growth, summon nature's ally I; Skill Knowledge (nature) DC 13; Cost 750 gp","ecology":"","habitat_society":""},{"name":"Grig","cr":1,"xp":400,"alignment":"NG","size":"Tiny","type":"fey","init":4,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":17,"ac_flat_footed":12,"ac_mods":"+4 Dex, +1 dodge, +2 size","hp":4,"hd":"1d6+1","hdvalue":1,"fort":1,"ref":6,"will":3,"dr":"5/cold iron","sr":16,"speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"short sword -1 (1d3-3/19-20)","ranged":"longbow +6 (1d4-3/x3)","space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"fiddle"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"disguise self"},{"spell":"entangle"},{"spell":"invisibility","details":"self only"},{"spell":"pyrotechnics"}]}],"strength":5,"dexterity":18,"constitution":13,"intelligence":10,"wisdom":13,"charisma":14,"baseatk":0,"cmb":2,"cmd":10,"cmd_special":"+6 vs. trip","feats":[{"feat":"Dodge"}],"skills":[{"skill":"Acrobatics","value":8,"special":"+12 when jumping"},{"skill":"Escape Artist","value":8},{"skill":"Fly","value":12},{"skill":"Perception","value":5},{"skill":"Perform (string)","value":6},{"skill":"Stealth","value":16}],"languages":["Common","Sylvan"],"environments":["temperate forests"],"organizations":["solitary","gang (2-5)","band (6-11)"],"treasure":"none","description_visual":"Perched on the prickly legs of a cricket, this tiny creature has gossamer wings and the upper body of an elven woman.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Fiddle","kind":"Su","details":"Grigs are capable of rubbing their legs together like a cricket to create a surprisingly pleasant sound not unlike that of a tiny fiddle. As a standard action, a grig can create a catchy tune that compels any creature within a 20-foot spread to dance and caper. A creature can resist this compulsion by making a DC 12 Will save. Creatures that fail are compelled to dance and shuffle their ft., and are effectively staggered as long as the grig continues to fiddle. A grig can maintain this effect for up to 10 rounds per day by concentrating. Once a creature makes the save against a grig's fiddle, it is immune to further fiddle effects from that grig for 24 hours. This is a sonic mind-affecting effect. The save DC is Charisma-based."}],"description":"Grigs are tiny fey with the upper bodies of elf-like sprites and cricket bodies below. Their humanoid features vary wildly in individual appearance, but they usually wear their brown, silver, or green hair long and uncombed. In most cases, grigs' skin bears gold or green stripes or markings, and their legs are brightly colored. They prefer to eschew clothes entirely, wearing clothing only when such apparel has desirable magical effects. Grigs stand 1-1/2 ft. tall, and weigh just under 10 pounds.\n\nGrigs make their homes in thick woods alongside rolling hills, often near bodies of water. In every grig community may be found a clearing where the group observes the moon during its many lunar holidays.\n\nDespite their tiny size, grigs are eager to confront evil and vanquish ugliness-as a result, grigs often find themselves in trouble. They rarely attack directly, instead preferring the element of surprise. In combat, grigs maintain their distance and either depend on their spell-like abilities or fire their longbows from afar. Grigs use their movement to their advantage, frequently jumping about their enemies or flying beyond their reach.\n\nGigs excel at music, and can create lively ditties simply by sawing their legs against their bodies. Grig music often stirs people to dance, even when the grigs don't enhance their music with supernatural compulsions. In addition to loving music, grigs enjoy the visual arts, especially paintings and sketches, and they often decorate their homes with bright colors and delightful images.","ecology":"","habitat_society":"","gear":"short sword, longbow with 20 arrows"},{"name":"Grioth","cr":1,"xp":400,"alignment":"CE","size":"Medium","type":"monstrous humanoid","init":4,"senses":[{"type":"blindsight","modifier":"20 ft."},{"type":"see in darkness"}],"ac":14,"ac_touch":14,"ac_flat_footed":10,"ac_mods":"+4 Dex","hp":13,"hd":"2d10+2","hdvalue":2,"fort":1,"ref":7,"will":6,"immunities":["cold"],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"mwk voidglass kukri +3 (1d4+1/18-20 plus 1d4 nonlethal), bite -3 (1d6 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"mindshock"}],"spell_like_abilities_caster_level":1,"spell_like_abilities_concentration":2,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"open/close"}]},{"frequency":"1/day","spells":[{"spell":"daze"},{"spell":"id insinuation"}]}],"strength":10,"dexterity":18,"constitution":12,"intelligence":13,"wisdom":13,"charisma":11,"baseatk":2,"cmb":2,"cmd":16,"feats":[{"feat":"Iron Will"}],"skills":[{"skill":"Fly","value":9},{"skill":"Knowledge (geography)","value":3},{"skill":"Perception","value":6,"special":"+10 in darkness"},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":9}],"languages":["Aklo","Grioth","telepathy 30 ft."],"sq":[{"type":"no breath"}],"environments":["any"],"organizations":["solitary","pair","gathering (3-6 plus 1 3rd-level cleric)","cult (7-20 plus 2-6 3rd-level clerics, 2-4 3rd-level barbarians, and 1 7th-level cleric)"],"treasure":"none","description_visual":"This lanky, batlike humanoid has a long tail and four narrow eyes. The silent creature moves with an unnerving grace.","source":"The Dragon's Demand","special_abilities":[{"type":"Id Insinuation","kind":"Sp","details":"As a standard action once per day, a grioth can disrupt a creature's mind. The target must be within 30 ft., and can resist this effect with a successful DC 12 Will save-otherwise, the target becomes confused for as long as the grioth concentrates plus 1 additional round after it ceases concentrating, to a maximum number of rounds equal to 3 plus the Grioth's total HD (5 rounds for most grioths). This is a mind-affecting effect, and is equivalent to a 2nd-level spell. The save DC is Charisma-based."},{"type":"Mindshock","kind":"Su","details":"When a grioth damages a creature with a voidglass weapon, a surge of the grioth's violent psychic energy pulses through the weapon, causing an additional 1d4 points of nonlethal damage. On a critical hit, the creature struck must also succeed at a DC 12 Will save or be confused for 1d2 rounds. This is a mind-affecting effect. The save DC is Charisma-based and includes a +2 racial bonus."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 12; frequency 1/round for 6 rounds; effect shaken for 1 round; cure 1 save."}],"description":"Grioths inhabit rogue planets that have been cast away from the stars. They often travel via portals to other worlds via that are undergoing eclipses to pillage resources that are rare on their frozen homeworlds. Many members of this evil race are known for their devotion to the Outer God Nyarlathotep (whom they worship in his guise as the Haunter of the Dark), and it isn't uncommon for colonies of grioths to be led by his clerics. Grioths' voices are raspy and dry. They favor weaponry crafted from a strange material known as voidglass.\n\nThe grioth race is prone to mutations, their forms twisted by the eldritch forces within the Dark Tapestry into lumbering giants or deformed horrors. Some grioths grow unusually large and ferocious, and the elders of the race possesses unusual and deadly psychic powers; abilities that aid them in ruling their dark spire cities and in their constant war against their hated foes, the entities of the Dominion of the Black.","ecology":"","habitat_society":"","gear":"masterwork voidglass kukri"},{"name":"Gryph","cr":1,"xp":400,"alignment":"NE","size":"Small","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":13,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 size","hp":15,"hd":"2d10+4","hdvalue":2,"fort":5,"ref":5,"will":1,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"bite +5 (1d6/x3), claw +5 (grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"implant eggs"}],"strength":11,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":12,"charisma":7,"baseatk":2,"cmb":1,"cmb_special":"+4 vs. start grapple, +8 vs. maintain grapple","cmd":13,"cmd_special":"+8 vs. trip","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":5},{"skill":"Stealth","value":10}],"environments":["temperate forests","temperate underground"],"organizations":["solitary","flock (2-8)","throng (9-20)"],"treasure":"incidental","description_visual":"This hawk-sized avian looks much like a six-legged stork. Its feathers are unkempt and greasy, and its beak is razor-sharp.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Grab","kind":"Ex","details":"A gryph can use its grab attack on a creature of up to Medium size. It has a +4 racial bonus on grapple checks to maintain a grapple (in addition to the +4 from the grab ability)."},{"type":"Implant Eggs","kind":"Ex","details":"Once per day, a gryph can implant eggs into a helpless target or a target it is grappling. As a fullround action, the gryph extends an ovipositor from its abdomen and penetrates the victim's flesh by making a successful sting attack (+5 melee). On a hit, the ovipositor deals 1 point of damage and implants 1d4 eggs in the victim. The eggs draw nutrients from the target's flesh, and give the target the sickened condition. The eggs grow swiftly, hatching in a mere 1d4 minutes into ravenous gryph chicks that immediately burrow out of the victim's body. This deals 2 points of Constitution damage per gryph chick, after which the hatchlings immediately take wing and fly away (if needed, use game statistics for a bat familiar to represent a hatchling). Removing implanted eggs requires a DC 20 Heal check (a full-round action); each attempt deals 1 hit point of damage. Although immunity to disease offers no special protection against gryph egg implantation, remove disease, heal, or similar effects automatically destroy any implanted gryph eggs."}],"description":"Gryphs are bird-like creatures usually found underground, but they also favor dark and tangled forests. Gryphs normally survive on carrion and small animals, but take on larger game when driven by hunger or if they feel threatened.\n\nMost disturbing is their means of reproduction. Gryphs are hermaphroditic and mate frequently, such that their egg pouches are rarely empty. When they encounter a suitable host-a warm-blooded creature of size Small or larger, ideally alone-the gryphs swoop down, latch on to the target, and implant their eggs directly into its flesh.\n\nAs long as the target is conscious, the flock continues its assault, though if the target flees the area, the gryphs return to their nest. The eggs quicken swiftly once implanted, and gryph chicks hatch forth mere minutes later in a bloody birth that is often fatal to the host.\n\nGryphs have a strange affinity for vermin, often lairing in close proximity to one or more insect swarms or vermin of Medium size or smaller. The insects avoid the gryphs instinctively, feeding off the remains of the flock's meals and on creatures too small for the gryphs to bother with.\n\nMost gryphs have six legs, but some have four or even eight. Individual flocks are always made up of gryphs with the same number of limbs. A gryph is 3 ft. tall and weighs 45 pounds.","ecology":"","habitat_society":""},{"name":"Hippocampus","cr":1,"xp":400,"alignment":"N","size":"Large","type":"magical beast","subtypes":["aquatic"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":12,"ac_touch":8,"ac_flat_footed":12,"ac_mods":"-1 Dex, +4 natural, -1 size","hp":15,"hd":"2d10+4","hdvalue":2,"fort":5,"ref":2,"will":1,"speed":[{"type":"land","speed":5},{"type":"swim","speed":60}],"melee":"bite +4 (1d4+3), tail slap -1 (1d4+1)","space":"10 ft.","reach":"5 ft.","strength":16,"dexterity":9,"constitution":15,"intelligence":2,"wisdom":12,"charisma":11,"baseatk":2,"cmb":6,"cmd":15,"feats":[{"feat":"Endurance"}],"skills":[{"skill":"Perception","value":6},{"skill":"Swim","value":11}],"sq":[{"type":"water dependency"}],"environments":["any water"],"organizations":["solitary","pair","school (3-16)"],"treasure":"none","description_visual":"This creature has the foreparts of a horse and the hindquarters of a fish. Its forelegs end in splayed fins rather than hooves.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Water Dependency","kind":"Ex","details":"A hippocampus can survive out of the water for 1 minute per point of Constitution. Beyond this limit, a hippocampus runs the risk of suffocation, as if it were drowning."}],"description":"A hippocampus's scales vary in color from ivory to deep green to cerulean blue with shades of silver.\n\nAquatic races such as merfolk and locathahs often train hippocampi as steeds or as draft animals used to pull cunningly designed underwater carriages. In the wild, hippocampi prefer to dwell in relatively shallow waters where their favorite food (seaweed and kelp) is more plentiful and larger predators are less common. These creatures often travel in large schools, analogous to free-roaming herds of wild horses on the surface world.\n\nThe hippocampus is relatively easily trained-the amount of work and cost it requires is equivalent to what it takes to train a horse. As armor impacts the creature's swim speed, those who train hippocampi for war rarely bother to put barding on these creatures-when they do, they generally opt for the lightest armor, such as padded or leather barding. Mounted combat on a hippocampus is similar to fighting while riding a horse, although the hippocampus is a clumsy creature on land and cannot move at all out of the water if it has a rider weighing it down. Although a hippocampus has only two front legs, determine its carrying capacity as if it were a quadruped. Thus, a light load for a hippocampus is up to 228 pounds. Medium loads are up to 459 pounds, and heavy loads up to 690 pounds.\n\nA number of variant species of hippocampus exist, although the majority of these species differ from the creature presented here only in color and feat choice.\n\nCommon feats other than Endurance for alternative hippocampus species are Great Fortitude, Improved Initiative, Iron Will, Lightning Ref lexes, Skill Focus (Swim), and Toughness. A few species of hippocampus are heartier and tougher all around-these creatures are generally those found in colder waters and are known as polar hippocampi. A polar hippocampus has the advanced creature simple template. Most impressive of all are hippocampi that dwell in the deeper seas. These creatures, known as giant hippocampi, are much larger; to generate stats for a giant hippocampus, advance the standard hippocampus to Huge size and increase its Hit Dice to 10. A giant hippocampus is CR 8.","ecology":"","habitat_society":""},{"name":"Hollow Helm","cr":1,"xp":400,"alignment":"NE","size":"Tiny","type":"undead","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+1 Dex, +3 natural, +2 size","hp":9,"hd":"2d8","hdvalue":2,"fort":0,"ref":1,"will":3,"defensive_abilities":["channel resistance +2"],"immunities":["undead traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"1 slam +4 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"skull cage"}],"strength":12,"dexterity":13,"wisdom":10,"charisma":10,"baseatk":1,"cmb":0,"cmd":11,"cmd_special":"cannot be tripped","feats":[{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":5},{"skill":"Stealth","value":12}],"languages":["Common (cannot speak)"],"sq":[{"type":"freeze"}],"treasure":"none","description_visual":"Though at first appearing to be an ordinary suit of armor, this imposing being begins to move, its lumbering movements slow and methodical.","group":"Phantom Armor","source":"AP 47","special_abilities":[{"type":"Freeze","kind":"Ex","details":"A hollow helm can hold itself so still it appears to be a normal suit of armor. A hollow helm that uses freeze can take 20 on its Stealth check to hide in plain sight, disguised as normal armor."},{"type":"Skull Cage","kind":"Ex","details":"A hollow helm sometimes pretends to be normal armor, letting a creature try to wear it before revealing its deadly nature. If the hollow helm makes a successful combat maneuver to grapple an opponent of Medium size or smaller, the grappled creature is also blinded. Creatures that purposefully try to wear a hollow helm are automatically grappled. This blindness lasts until the hollow helm's grapple is broken. A hollow helm cannot attack a creature it is grappling. If a hollow helm is damaged while it is grappling, the creature it is grappling takes an equal amount of damage."}],"description":"Raised from the corpses of knights and soldiers slain by treachery rather than battle or conflicts considered crimes even in the heat of war, phantom armors appear as suits of animate armor, walking or floating of their own accord. Most phantom armors haunt the halls and blasted battlefields where they were slain, seeking revenge against their murderers or, should that prove impossible, confronting any living creature that might give them the opportunity to do battle once more. Dastardly necromancers have also discovered the process for binding violent spirits to suits of armor, giving rise to eerie servants that combine endless patience with cold brutality. Phantom armors come in many shapes and sizes; some appear to be nothing more than animate helms while others resemble armored giants. Ecology Phantom armors-being undead and having no need for sleep or sustenance-make perfect guards, especially given their single-minded demeanors and their innocuous appearances. While a phantom armor's \"suit\" is hollow, the spirit of a dead warrior still inhabits it, forever caught in the cold embrace of steel and forced servitude until it is defeated in battle. Of course, since not all suits of armor are alike, neither are all phantom armors. Horrific tales tell of ghastly knights floating through haunted corridors, their helmet visors revealing only blackness within. The animating spirit of a phantom armor is typically invisible, the armored shell appearing to be the entirety of the creature. Casting spells like see invisibility or detect undead reveals the vague shape of a spirit seemingly wearing the armor. Creating Phantom Armor Phantom armors of varying types can be created using the spell create undead, as detailed below. In addition to requiring a corpse for it to be cast upon, the spell requires that body must be wearing a suit of heavy armor. The corpse dissolves into the armor at the conclusion of the spell's casting. Caster Level Phantom Armor Created 11th or lower Hollow helm 12th-13th Guardian phantom armor 14th Floating phantom armor 15th Giant phantom armor 16th Phantom lancer.","ecology":"Phantom armors-being undead and having no need for sleep or sustenance-make perfect guards, especially given their single-minded demeanors and their innocuous appearances. While a phantom armor's \"suit\" is hollow, the spirit of a dead warrior still inhabits it, forever caught in the cold embrace of steel and forced servitude until it is defeated in battle. Of course, since not all suits of armor are alike, neither are all phantom armors. Horrific tales tell of ghastly knights floating through haunted corridors, their helmet visors revealing only blackness within. The animating spirit of a phantom armor is typically invisible, the armored shell appearing to be the entirety of the creature. Casting spells like see invisibility or detect undead reveals the vague shape of a spirit seemingly wearing the armor. Creating Phantom Armor Phantom armors of varying types can be created using the spell create undead, as detailed below. In addition to requiring a corpse for it to be cast upon, the spell requires that body must be wearing a suit of heavy armor. The corpse dissolves into the armor at the conclusion of the spell's casting. Caster Level Phantom Armor Created 11th or lower Hollow helm 12th-13th Guardian phantom armor 14th Floating phantom armor 15th Giant phantom armor 16th Phantom lancer.","habitat_society":""},{"name":"Homunculus","cr":1,"xp":400,"alignment":"Any (same as creator)","size":"Tiny","type":"construct","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":11,"hd":"2d10","hdvalue":2,"fort":0,"ref":4,"will":1,"defensive_abilities":["construct traits"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":50,"maneuverability":"good"}],"melee":"1 bite +3 (1d4-1  plus poison)","space":"2-1/2 ft.","reach":"0 ft.","strength":8,"dexterity":15,"intelligence":10,"wisdom":12,"charisma":7,"baseatk":2,"cmb":2,"cmd":11,"feats":[{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":3},{"skill":"Stealth","value":12}],"languages":["Common (cannot speak)","telepathic link"],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This vaguely humanoid creature is about the size of a cat but looks more like a toothy, winged devil.","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 13; frequency 1/minute for 60 minutes; effect sleep for 1 minute; cure 1 save. The save DC is Constitution-based and includes a +2 racial bonus."},{"type":"Telepathic Link","kind":"Su","details":"A homunculus cannot speak, but the process of creating one links it telepathically with its creator. A homunculus knows what its master knows and can convey to him or her everything it sees and hears, out to a distance of 1,500 ft."}],"description":"A homunculus is a miniature servant created by a spellcaster from his own blood. They are weak combatants but make effective spies, messengers, and scouts. A homunculus's creator determines its precise features; some are more refined looking, but most creators don't bother to improve the creature's appearance beyond the minimum necessary for functioning.\n\nHomunculi are little more than tools designed to carry out assigned tasks. They are extensions of their creators, sharing the same alignment and basic nature.\n\nA homunculus never willingly travels more than a mile from its master, though it can be removed forcibly. If this occurs, the creature does everything in its power to return to this range, as it cannot communicate with its master beyond this distance. An attack that destroys a homunculus deals 2d10 points of damage to its master. If the creature's master is slain, the homunculus goes insane-it loses its Intelligence score, all feats, and all skill ranks, and generally claims the immediate surroundings as its domain, mindlessly attacking any who intrude upon its lair.\n\nOn rare occasions, a homunculus freed from its servitude rises above its master's original intent and becomes more than a half-insane construct guardian of a long-forgotten lair. In some cases, a homunculus might even come to see itself as the rightful heir to its master's legacy, or even the reincarnated spirit of the master himself.\n\nConstruction A homunculus is shaped from a mixture of clay, ash, mandrake root, spring water, and one pint of the creator's own blood. These materials cost 50 gp. After the body is sculpted, it is animated through an extended magical ritual that requires a specially prepared laboratory or workroom, similar to an alchemist's laboratory, and costing an additional 1,000 gp to supply. If the creator is personally constructing the creature's body, the building and ritual can be performed together. A homunculus with more than 2 Hit Dice can be created, but each additional Hit Die adds +2,000 gp to the cost to create.\n\nThe person whose blood is used to form a homunculus's body becomes its master; it is possible for one person to give blood for the creation, another to sculpt the base material, and another to magically animate it as a minion for the one who provided the blood.\n\nHomunculus CL 7th; Price 2,050 gp Construction Requirements Craft Construct, arcane eye, mirror image, mending; Skill Craft (leather) or Craft (sculptures) DC 12; Cost 1,050 gp.","ecology":"","habitat_society":""},{"name":"Horse","cr":1,"xp":400,"alignment":"N","size":"Large","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":11,"ac_touch":11,"ac_flat_footed":9,"ac_mods":"+2 Dex, -1 size","hp":15,"hd":"2d8+6","hdvalue":2,"fort":6,"ref":5,"will":1,"speed":[{"type":"land","speed":50}],"melee":"2 hooves -2 (1d4+1)","space":"10 ft.","reach":"5 ft.","strength":16,"dexterity":14,"constitution":17,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":1,"cmb":5,"cmd":17,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Run","type":"bonus"}],"skills":[{"skill":"Perception","value":6}],"sq":[{"type":"docile"}],"environments":["temperate plains"],"organizations":["solitary","pair","herd (3-30)"],"treasure":"none","description_visual":"This proud horse thunders across the grassy plain with fluid grace, wind tugging at its loose-fitting barding.","source":"PFRPG Bestiary","special_abilities":[{"type":"Docile","kind":"Ex","details":"Unless specifically trained for combat (see the Handle Animal skill), a horse's hooves are treated as secondary attacks. Horses stand 5 to 6 ft. tall at the shoulder and weigh between 1,000 and 1,500 pounds."}],"description":"The statistics above are for a typical riding horse, called by some a \"light horse.\" Some horses are larger and heartier, bred for labor such as pulling plows or carriages. These horses are called \"heavy horses\" and gain the following adjustments to the base statistics detailed above.\n\nHeavy Horse: A heavy horse gains the advanced simple template. In addition, it also gains a bite attack that inf licts 1d4 damage, and its hoof damage increases to 1d6. As with a light horse, a heavy horse can be specifically trained for combat with the Handle Animal skill.","ecology":"","habitat_society":""},{"name":"Hunter Urchin","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"vermin","subtypes":["aquatic"],"init":-4,"senses":[{"type":"all-around vision"},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"30 ft."}],"ac":12,"ac_touch":6,"ac_flat_footed":12,"ac_mods":"-4 Dex, +6 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":-4,"will":0,"defensive_abilities":["stability"],"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":15}],"melee":"tongue +3 (1d3+3 plus pull)","space":"5 ft.","reach":"5 ft. (20 ft. with tongue)","special_attacks":[{"type":"spines","details":"+3, 1d4+2 plus poison"},{"type":"pull","details":"tongue, 5 ft."}],"strength":15,"dexterity":3,"constitution":14,"wisdom":11,"charisma":2,"baseatk":1,"cmb":3,"cmd":9,"cmd_special":"+8 vs. bull rush or trip","skills":[{"skill":"Perception","value":4}],"sq":[{"type":"amphibious"}],"environments":["temperate coastlines","temperate oceans","warm coastlines","warm oceans"],"organizations":["solitary","pair","cluster (3-10)"],"treasure":"none","description_visual":"This strange-looking creature has a spherical body covered with hundreds or thousands of two-foot-long bright purple spines that darken to ominous black tips.","group":"Giant","source":"AP 37","special_abilities":[{"type":"All-Around Vision","kind":"Ex","details":"All giant sea urchins can see in all directions. They gain a +4 racial bonus on Perception checks and cannot be flanked."},{"type":"Poison","kind":"Ex","details":"Hunter urchin venom causes intense pain that staggers those who suffer its effects, but doesn't actually inflict ability damage. The save DC is Constitution-based. Spines-injury; save Fort DC 13; frequency 1/round for 6 rounds; effect staggered for 1 round; cure 1 save."},{"type":"Spines","kind":"Ex","details":"A hunter urchin's spines can swivel to face any approaching creature. Any creature that attacks a hunter urchin with an unarmed strike or a natural attack, or any Medium or smaller creature that attacks with a one-handed weapon or light weapon, is automatically attacked by the hunter urchin's spines as an immediate action. If the spines hit, they can poison the target as well."},{"type":"Stability","kind":"Ex","details":"All giant sea urchins receive a +8 bonus to CMD when resisting a bull rush or trip attempt."}],"description":"Much more dangerous than their smaller kin, giant sea urchins are dangerous predators of opportunity. With the exception of the hunter urchin, giant sea urchins lie in wait for food to come to them, typically carried within reach of their attacks via ocean currents or, more commonly, tides. Hunter Urchins: These urchins can adjust their spines to effect an awkward method of locomotion on land. They actively seek prey, and possess long, rasp-like tongues that can whip out and pull food to them. Spear Urchins: These brightly colored creatures can fire spines like javelins, relying upon poison to slow down prey or eventually immobilize it so they can crawl over to feed. Glass Urchins: So named for their transparency, these beautiful creatures shimmer like delicate crystals. Yet for all the damage their spines can inf lict, victims of glass urchins generally do more damage to themselves or their allies due to the potent hallucinatory effects of this urchin's venom. Sea Urchins as Difficult Terrain The giant sea urchins presented here are fantastic evolutions of their much more common, smaller, and less offensive kin. Yet even the smaller common urchins can pose a problem for unwary adventurers. Sea urchins live in vast colonies on tidal rocks, and moving across a field of urchins can be quite awkward and painful. Their thousands of spines are just as sharp as those possessed by their larger kin, and they function as caltrops to anyone that walks over them. Worse, these spines are venomous, and can poison those who take damage from them. Those who succumb to the poison suffer searing pain that can sicken them for several minutes. Though uncomfortable, fortunately this venom doesn't actually inf lict either ability damage or ability drain. Sea Urchin Venom: Spines-injury; save Fort 11; frequency 1/minute for 6 minutes; effect victim is sickened for 1 minute; cure 1 save.","ecology":"","habitat_society":""},{"name":"Hyena","cr":1,"xp":400,"alignment":"N","size":"Medium","type":"animal","init":2,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":5,"will":1,"speed":[{"type":"land","speed":50}],"melee":"bite +3 (1d6+3 plus trip)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":15,"constitution":15,"intelligence":2,"wisdom":13,"charisma":6,"baseatk":1,"cmb":3,"cmd":15,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":6,"special":"+10 in tall grass"}],"environments":["warm plains"],"organizations":["solitary","pair","pack (3-12)"],"treasure":"none","description_visual":"This hyena is covered in shaggy, tan-colored fur with black and brown stripes.","source":"PFRPG Bestiary","description":"Hyenas are pack hunters infamous for their cunning and their unnerving, laughter-like vocalizations. They are largely scavengers, but aren't above supplementing their diet of carrion with fresh prey. Hyenas tend to hunt alone, but when hunting as a pack they typically send one or two members against a foe's front while the rest of the pack circles and attacks from behind. Many of the savage humanoid races, particularly gnolls, use hyenas as guard dogs. Such hyenas typically wear leather barding and are trained from birth to be vicious and savage-many such creatures are advanced hyenas.","ecology":"","habitat_society":""}];
